<?php
namespace App\Commands;
use CodeIgniter\CLI\{BaseCommand,CLI};
final class IkontrolAdminDiagnose extends BaseCommand{protected $group='iKontrol';protected $name='ikontrol:admin-diagnose';public function run(array$p){if(count($p)!==1||!filter_var($p[0],FILTER_VALIDATE_EMAIL))throw new \RuntimeException('Correo inválido.');$emit=fn($data)=>CLI::write("IKONTROL_JSON_BEGIN\n".json_encode($data)."\nIKONTROL_JSON_END");$db=\Config\Database::connect();$tables=array_flip($db->listTables());$name=fn($n)=>$db->prefixTable($n);$result=['user_exists'=>false,'active'=>false,'staff'=>false,'role_ok'=>false,'permissions_ok'=>false,'profile_ok'=>false,'required_relation'=>['table'=>'team_member_job_info','foreign_key'=>'user_id','expected'=>'exactly_one_active_row','actual'=>0],'dashboard_prerequisites'=>[],'status'=>'FAILED','reason'=>null];if(!isset($tables[$name('users')])){$result['dashboard_prerequisites']['users_table']=false;$result['reason']='TABLE_MISSING';$emit($result);return;}$user=$db->table('users')->select('id,user_type,is_admin,role_id,status,disable_login,deleted')->where('email',strtolower($p[0]))->get()->getRowArray();if(!$user){$result['reason']='USER_NOT_FOUND';$emit($result);return;}$result['user_exists']=true;$result['active']=$user['status']==='active'&&!(int)$user['disable_login']&&!(int)$user['deleted'];$result['staff']=$user['user_type']==='staff';$result['role_ok']=(int)$user['is_admin']===1&&((int)$user['role_id']===0);$result['permissions_ok']=$result['role_ok'];$jobTable=isset($tables[$name('team_member_job_info')]);$jobCount=$jobTable?$db->table('team_member_job_info')->where(['user_id'=>$user['id'],'deleted'=>0])->countAllResults():0;$result['required_relation']['actual']=$jobCount;$result['profile_ok']=$jobCount===1;foreach(['settings','dashboards','team']as$t)$result['dashboard_prerequisites'][$t.'_table']=isset($tables[$name($t)]);$critical=$result['active']&&$result['staff']&&$result['role_ok']&&$result['permissions_ok']&&!in_array(false,$result['dashboard_prerequisites'],true);$result['status']=$critical&&$result['profile_ok']?'READY':'FAILED';$result['reason']=!$result['active']?'INACTIVE':(!$result['role_ok']?'ROLE_MISSING':(!$result['permissions_ok']?'PERMISSIONS_MISSING':(!$result['profile_ok']?'TEAM_MEMBER_INFO_MISSING':(in_array(false,$result['dashboard_prerequisites'],true)?'TABLE_MISSING':null))));$emit($result);}}